<template><details class="vault-importer m-card"><summary><FolderInput :size="20"/><span>导入 Obsidian / Markdown 知识库</span><ChevronDown :size="17"/></summary><p class="workspace-caption">只处理你主动选择的 MD、MDX、TXT。正文保存在服务器，目录、Frontmatter 与链接关系按账号保存在本机；MDX 作为文本，不执行代码。</p><div class="vault-file-pickers"><label class="m-btn m-btn--ghost m-btn--sm"><Files :size="16"/>选择多个文件<input type="file" accept=".md,.mdx,.txt" multiple @change="selectFiles"/></label><label class="m-btn m-btn--ghost m-btn--sm"><FolderOpen :size="16"/>选择目录（浏览器支持时）<input type="file" webkitdirectory multiple @change="selectFiles"/></label></div><div v-if="items.length" class="vault-preview"><h3>导入预览 · {{ items.length }} 份文件</h3><p class="workspace-caption">{{ duplicateCount }} 个文件与现有资料同名。确认后才会写入；停止后已完成的导入会保留。</p><label class="m-field"><span>遇到重复文件时</span><select v-model="strategy" class="m-input" :disabled="busy"><option value="skip">跳过重复文件</option><option value="overwrite">覆盖原文（需确认）</option><option value="copy">保留副本</option></select></label><ul><li v-for="item in items" :key="item.doc.path"><code>{{ item.doc.path }}</code><span>{{ item.doc.headings.length }} 个标题 · {{ item.doc.links.length }} 个链接{{ item.existingId?' · 重复':'' }}</span></li></ul><div class="workspace-actions"><button class="m-btn m-btn--primary m-btn--sm" :disabled="busy" @click="confirmOpen=true">预览无误，确认导入</button><button v-if="busy" class="m-btn m-btn--ghost m-btn--sm" @click="cancelled=true">停止后续导入</button><button v-else class="workspace-text-action" @click="items=[]">取消预览</button></div></div><p v-if="busy" role="status" class="workspace-caption">正在导入 {{ processed }} / {{ items.length }} …</p><p v-if="message" role="status" class="workspace-caption">{{ message }}</p><ul v-if="errors.length" class="vault-errors" role="alert"><li v-for="error in errors" :key="error">{{ error }}</li></ul><AppDialog v-model="confirmOpen" title="确认导入这些文件？" :persistent="busy"><p>将向当前账号添加 {{ items.length }} 份资料。{{ strategy==='overwrite'?'同名文件的原文会被替换，请确保已经保留需要的版本。':'同名文件将按你选择的策略处理。' }}</p><p class="workspace-caption">基础 Frontmatter 支持单行字段与标签列表。尚未导入的链接目标会显示为未解析，不生成虚构笔记。</p><template #footer><button class="m-btn m-btn--ghost" :disabled="busy" @click="confirmOpen=false">返回检查</button><button class="m-btn m-btn--primary" :disabled="busy" @click="importFiles">确认保存到我的资料库</button></template></AppDialog></details></template>
<script setup lang="ts">
import { computed,onBeforeUnmount,ref } from 'vue'
import { ChevronDown,Files,FolderInput,FolderOpen } from 'lucide-vue-next'
import { parseMarkdown,type VaultDocument } from '@/mobile/domain/markdown-vault'
import { useLearningWorkspace } from '@/mobile/stores/learning-workspace'
import { currentEpoch } from '@/mobile/data/learning-data'
import { changeWorkspace } from '@/mobile/data/workspace'
import AppDialog from './AppDialog.vue'
const emit=defineEmits<{imported:[]}>(),store=useLearningWorkspace(),items=ref<Array<{doc:VaultDocument;existingId:string|null}>>([]),strategy=ref('skip'),busy=ref(false),confirmOpen=ref(false),cancelled=ref(false),processed=ref(0),message=ref(''),errors=ref<string[]>([])
let alive=true
onBeforeUnmount(()=>{alive=false;cancelled.value=true})
const duplicateCount=computed(()=>items.value.filter(item=>item.existingId).length)
async function selectFiles(event:Event){errors.value=[];message.value='';const files=Array.from((event.target as HTMLInputElement).files||[]);if(files.length>40){errors.value=['每次最多导入 40 个文本文件，请分批选择。'];return};const selected:typeof items.value=[];let bytes=0;for(const file of files){if(!/\.(md|mdx|txt)$/i.test(file.name))continue;try{bytes+=file.size;if(bytes>2*1024*1024)throw new Error('本批文本超过 2 MB，请拆分以便保留本机目录索引。');const raw=await file.text(),relative=(file as File&{webkitRelativePath?:string}).webkitRelativePath||file.name,doc=parseMarkdown(relative,raw),existing=store.workspace?.materials.find(m=>m.title===doc.path);selected.push({doc,existingId:existing?.id||null})}catch(e){errors.value.push(`${file.name}：${e instanceof Error?e.message:'无法读取'}`)}}items.value=selected;if(!selected.length&&!errors.value.length)errors.value=['所选目录没有受支持的文本文件。'];(event.target as HTMLInputElement).value=''}
async function importFiles(){busy.value=true;cancelled.value=false;processed.value=0;errors.value=[];let saved=0,skipped=0;const initialScope=store.scope,initialEpoch=currentEpoch();const isCurrent=()=>alive&&store.scope===initialScope&&currentEpoch()===initialEpoch;try{for(const item of items.value){if(cancelled.value||!isCurrent())break;processed.value++;if(item.existingId&&strategy.value==='skip'){skipped++;continue}try{let materialId=item.existingId;let doc=item.doc;if(materialId&&strategy.value==='overwrite'){await changeWorkspace(`materials/${materialId}`,{content:doc.raw})}else{if(materialId&&strategy.value==='copy')doc={...doc,path:doc.path.replace(/(\.[^.]+)$/,` (副本 ${Date.now().toString().slice(-5)})$1`)};const result=await changeWorkspace<{result:{id:string}}>('materials',{kind:'text',title:doc.path,content:doc.raw,tags:doc.tags.join(',')});materialId=result.result.id}if(!isCurrent())break;store.local.vault[materialId!]={...doc,materialId:materialId!,importedAt:new Date().toISOString()};store.persist();saved++}catch(e){errors.value.push(`${item.doc.path}：${e instanceof Error?e.message:'保存失败'}`)}}if(!isCurrent())return;await store.refresh();message.value=`已保存 ${saved} 份，跳过 ${skipped} 份${cancelled.value?'；后续导入已停止':''}。${store.storageError?'目录索引未持久化，请保留原始文件。':''}`;confirmOpen.value=false;if(!errors.value.length&&!cancelled.value)items.value=[];emit('imported')}finally{busy.value=false}}
</script>
<style scoped>.vault-importer{margin:18px 0}.vault-importer>summary{display:flex;align-items:center;gap:10px;list-style:none;min-height:44px;font-size:14px;cursor:pointer;color:var(--m-primary)}.vault-importer>summary>span{flex:1}.vault-file-pickers{display:flex;gap:10px;flex-wrap:wrap}.vault-file-pickers label{position:relative;cursor:pointer}.vault-file-pickers input{position:absolute;opacity:0;inset:0;width:100%;cursor:pointer}.vault-preview h3{font-size:18px}.vault-preview ul{list-style:none;padding:0;margin:16px 0;max-height:230px;overflow:auto}.vault-preview li{display:grid;gap:6px;padding:10px 0;border-bottom:1px solid var(--m-border)}.vault-preview code{font-size:13px;overflow-wrap:anywhere}.vault-preview li>span{font-size:12px;color:var(--m-text-faint)}.vault-errors{padding-left:18px;color:var(--m-danger);font-size:13px;line-height:1.9}</style>
